import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react'
import { ArrowDownToLine, ArrowRight, ArrowLeft, BarChart3, Bell, BookOpen, Bot, CalendarDays, Check, CheckCheck, CheckCircle2, ChevronDown, ChevronRight, Clock3, FileText, GraduationCap, Home, Layers3, ListTodo, Menu, Plus, Search, Settings2, ShieldCheck, Sparkles, Users, UserRound, X, RefreshCw, CircleAlert, CircleHelp, ArrowLeftRight, History, Play, Send, School, Wallet, ReceiptText, Download, Filter, LoaderCircle } from 'lucide-react'
import type { AppState, Role, Lesson, Teacher } from './types'
import AcademicPages from './AcademicPages'
import ScheduleWorkspace from './ScheduleWorkspace'
import SchoolApp from './SchoolApp'
import { apiFetch, appUrl, PORTAL_HOME, PORTAL_LOGIN, PORTAL_MODE, SESSION_EXPIRED_EVENT } from './api'
import {createPortal} from 'react-dom'

const titles: Record<string,string> = { overview:'Главная', schedule:'Расписание', replacements:'Замены', students:'Ученики', teachers:'Учителя', tasks:'Задачи и процессы', documents:'Документы', clubs:'Кружки и квитанции', analytics:'Аналитика школы', assistant:'ИИ-помощник', history:'История действий', settings:'Настройки', 'student-home':'Кабинет ученика', 'teacher-home':'Кабинет учителя', 'my-lessons':'Мои уроки', assignments:'Задания', grades:'Оценки', progress:'Мой прогресс', library:'Библиотека', classes:'Классы', materials:'Материалы', review:'Проверка работ' }
const roleNames:Record<Role,string>={director:'Директор',admin:'Завуч',teacher:'Учитель',student:'Ученик',accountant:'Бухгалтер'}
const navItems = [ ['overview',Home],['schedule',CalendarDays],['replacements',ArrowLeftRight],['students',Users],['teachers',UserRound],['classes',Layers3],['tasks',ListTodo],['documents',FileText],['clubs',ReceiptText],['analytics',BarChart3] ] as const
const studentNav = [['student-home',Home],['my-lessons',CalendarDays],['assignments',ListTodo],['grades',BarChart3],['progress',Sparkles],['clubs',ReceiptText],['library',BookOpen]] as const
const teacherNav = [['teacher-home',Home],['schedule',CalendarDays],['replacements',ArrowLeftRight],['classes',Layers3],['materials',BookOpen],['review',CheckCheck],['tasks',ListTodo],['documents',FileText]] as const
const descriptions:Record<string,string>={overview:'Вся школа в одном месте. Актуальная информация и результаты.',schedule:'Рабочий черновик, изменения и проверка занятости.',replacements:'Подбор замены, согласование и контроль проведения урока.',students:'Учебная работа, посещаемость и адресная помощь.',teachers:'Преподаватели, предметы и учебная нагрузка.',tasks:'От школьного события до подтверждённого результата.',documents:'Единый маршрут подготовки и согласования.',clubs:'Кружки, демонстрационные тарифы и квитанции ученикам.',analytics:'Успеваемость, посещаемость и нагрузка преподавателей.',assistant:'Помощь в школьных процессах и учебных задачах.',history:'Кто, когда и что изменил. Каждый результат можно проверить.',settings:PORTAL_MODE?'Параметры школьного кабинета.':'Параметры локальной демонстрации.'}

export async function api(path:string,body?:unknown){
 const response=await apiFetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'})
 if(!response.ok){let msg='Не удалось выполнить действие';try{const r=await response.json();msg=typeof r.detail==='string'?r.detail:response.status===422?'Проверьте заполненные поля':msg}catch{};throw new Error(msg)}
 return response.json()
}
function saveFile(name:string,content:string,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const fmt=(n:number)=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(n/100)
function timeText(value:string){const d=new Date(value);return Number.isNaN(d.getTime())?value:d.toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Moscow'})}
function Avatar({name,color='blue',small=false}:{name:string;color?:string;small?:boolean}){
 const portrait=name.includes('Fictional-d09ad-7')?'portrait-0':name.includes('Fictional-d0a1d-8')?'portrait-1':name.includes('Fictional-d092d-9')?'portrait-2':name.includes('Fictional-d0a1d-10')&&!name.includes('Fictional-d090d-11')?'portrait-3':''
 return <span aria-hidden="true" className={`avatar ${color} ${small?'small':''} ${portrait}`}>{!portrait&&name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span>
}
function Glossy({icon:Icon,tone='blue'}:{icon:typeof Users;tone?:string}){return <span className={`glossy ${tone}`}><Icon size={29} strokeWidth={2.3}/></span>}
function Tag({children,tone='blue'}:{children:ReactNode;tone?:string}){return <span className={`tag ${tone}`}>{children}</span>}
function Stat({icon:Icon,tone,label,value,detail}:{icon:typeof Users;tone:string;label:string;value:ReactNode;detail:ReactNode}){return <div className={`stat ${tone}`}><Glossy icon={Icon} tone={tone}/><div><span>{label}</span><strong>{value}</strong><small>{detail}</small></div></div>}
function Empty({children='Пока ничего нет'}:{children?:ReactNode}){return <div className="empty"><Layers3 size={32}/><p>{children}</p></div>}
function Card({title,action,children,className=''}:{title?:ReactNode;action?:ReactNode;children:ReactNode;className?:string}){return <section className={`card ${className}`}>{title&&<div className="card-head"><h2>{title}</h2>{action}</div>}{children}</section>}
function Modal({title,children,onClose}:{title:string;children:ReactNode;onClose:()=>void}){
 const ref=useRef<HTMLDivElement>(null),closeRef=useRef(onClose)
 closeRef.current=onClose
 useEffect(()=>{const previous=document.activeElement as HTMLElement;const old=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.querySelector<HTMLElement>('button,input,textarea,select')?.focus();function handler(e:KeyboardEvent){if(e.key==='Escape')closeRef.current();if(e.key==='Tab'){const all=[...ref.current!.querySelectorAll<HTMLElement>('button:not(:disabled),input,textarea,select,a[href]')];const first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}document.addEventListener('keydown',handler);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',handler);previous?.focus()}},[])
 return createPortal(<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div ref={ref} className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="card-head"><h2 id="modal-title">{title}</h2><button className="icon-btn" onClick={onClose} aria-label="Закрыть"><X/></button></div>{children}</div></div>,document.body)
}

export default function App(){
 const [state,setState]=useState<AppState|null>(null),[error,setError]=useState(''),[page,setPage]=useState(location.hash.slice(1)||'overview'),[busy,setBusy]=useState(false),[toastMessage,setToast]=useState(''),[mobile,setMobile]=useState(false),[search,setSearch]=useState(''),[notifications,setNotifications]=useState(false),[modal,setModal]=useState<ReactNode>(null),[modalTitle,setModalTitle]=useState(''),[demoChoice,setDemoChoice]=useState('director'),[needsLogin,setNeedsLogin]=useState(false)
 const toast=useCallback((message:string)=>{setToast(message)},[])
 useEffect(()=>{if(!toastMessage)return;const id=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(id)},[toastMessage])
 const load=useCallback(async()=>{const data=await api('/api/state');setState(data);setError('');return data},[])
 useEffect(()=>{if(!PORTAL_MODE)return;const expired=()=>{setNeedsLogin(true);setState(null)};window.addEventListener(SESSION_EXPIRED_EVENT,expired);return()=>window.removeEventListener(SESSION_EXPIRED_EVENT,expired)},[])
 const initialize=useCallback(async()=>{
  setBusy(true)
  try {
   const response=await apiFetch('/api/state')
   if(response.status===401){
    if(PORTAL_MODE){setNeedsLogin(true);return}
    await api('/api/demo/session',{role:'director'});await load()
   }else if(response.ok){const d=await response.json();setState(d);setError('');setDemoChoice(d.role==='teacher'&&d.profile.name.includes('Fictional-d0a1d-8')?'teacher:t2':d.role)}
   else throw new Error(response.status===403?'Доступ к школьному кабинету не разрешён.':'Сервер недоступен')
  }catch(e){setError(e instanceof Error?e.message:'Нет связи с сервером')}
  finally{setBusy(false)}
 },[load])
 useEffect(()=>{void initialize()},[initialize])
 const navigate=useCallback((next:string)=>{setPage(next);location.hash=next;setMobile(false);setSearch('');window.scrollTo({top:0,behavior:'instant'})},[])
 useEffect(()=>{const listener=()=>setPage(location.hash.slice(1)||'overview');window.addEventListener('hashchange',listener);return()=>window.removeEventListener('hashchange',listener)},[])
 const mutate=useCallback(async(path:string,body:unknown={})=>{setBusy(true);try{await api(path,body);await load()}catch(e){toast(e instanceof Error?e.message:'Не удалось сохранить');throw e}finally{setBusy(false)}},[load,toast])
 const switchRole=async(choice:string)=>{if(PORTAL_MODE)return;setBusy(true);try{const [role,teacherId]=choice.split(':');await api('/api/demo/session',{role,...(teacherId?{teacherId}: {})});setDemoChoice(choice);await load();navigate(role==='student'?'student-home':role==='teacher'?'teacher-home':'overview');toast('Открыт демонстрационный кабинет')}catch(e){toast(e instanceof Error?e.message:'Не удалось переключиться')}finally{setBusy(false)}}
 const closeModal=useCallback(()=>setModal(null),[])
 function openModal(title:string,content:ReactNode){setModalTitle(title);setModal(content)}
 if(PORTAL_MODE&&needsLogin)return <div className={`startup${PORTAL_MODE?' school-startup school-app cp-design':''}`}><span className="brand-icon"><GraduationCap/></span><h1>Школа<span>.Действие</span></h1><p role="alert">Сессия личного кабинета завершилась. Войдите, чтобы продолжить.</p><a className="btn btn-primary" href={PORTAL_LOGIN}>Войти в личный кабинет <ArrowRight size={16}/></a><a className="text-btn" href={PORTAL_HOME}>Вернуться в личный кабинет</a></div>
 if(!state)return <div className={`startup${PORTAL_MODE?' school-startup school-app cp-design':''}`}><span className="brand-icon"><GraduationCap/></span><h1>Школа<span>.Действие</span></h1>{error?<><p>{PORTAL_MODE?'Не удалось открыть школьный кабинет.':'Не удаётся связаться с локальным сервером.'}</p><small role="alert">{error}</small><button className="btn btn-primary" onClick={()=>void initialize()}>Повторить подключение</button>{PORTAL_MODE?<a className="text-btn" href={PORTAL_HOME}>Вернуться в личный кабинет</a>:<p className="muted">Запустите приложение по инструкции «Начать здесь».</p>}</>:<><LoaderCircle className="spin"/><p>Открываем школьный кабинет…</p></>}</div>
 if((state as AppState & {workspaceMode?:string}).workspaceMode==='school')return <SchoolApp state={state}/>
 const role=state.role
 const nav=role==='student'?studentNav:role==='teacher'?teacherNav:navItems.filter(([id])=>role==='accountant'?['overview','tasks','documents','clubs'].includes(id):role==='admin'?id!=='clubs':id!=='classes')
 const allAllowed=new Set([...nav.map(([id])=>id), 'assistant',...(role!=='student'?['history','settings']:[])])
 const active=allAllowed.has(page)?page:role==='student'?'student-home':role==='teacher'?'teacher-home':'overview'
 const academic=['student-home','teacher-home','my-lessons','assignments','grades','progress','library','classes','materials','review'].includes(active)
 const pending=state.replacements.filter(r=>r.status==='pending').length
 const unread=state.notifications.filter(n=>!n.read).length
 const results=search.trim()?[
 ...nav.map(([id])=>({id,title:titles[id],subtitle:'Раздел платформы',go:()=>navigate(id)})),
 ...state.students.map(s=>({id:s.id,title:s.name,subtitle:`Ученик · ${s.className}`,go:()=>{navigate('students');setSearch('')}})),
 ...state.documents.map(d=>({id:d.id,title:d.title,subtitle:'Документ',go:()=>navigate('documents')})),
 ...state.tasks.map(t=>({id:t.id,title:t.title,subtitle:'Задача',go:()=>navigate('tasks')}))
 ].filter(x=>(x.title+' '+x.subtitle).toLowerCase().includes(search.toLowerCase())).slice(0,8):[]
 return <div className="app-layout">
  {mobile&&<div className="sidebar-scrim" onClick={()=>setMobile(false)}/>}
  <aside className={`sidebar ${mobile?'open':''}`}><a className="brand" href={`#${role==='student'?'student-home':role==='teacher'?'teacher-home':'overview'}`} onClick={()=>setMobile(false)}><span className="brand-icon brand-book"><BookOpen size={27}/></span><span>Школа<span className="brand-accent">.Действие</span></span></a><div className="school-label"><School size={18}/><div>{PORTAL_MODE?state.school.name:'Oakbridge School'}<small>{PORTAL_MODE?'Закрытый школьный кабинет':'Демонстрационная школа'}</small></div></div><div className="nav-caption">РАБОЧЕЕ ПРОСТРАНСТВО</div><nav aria-label="Основная навигация">{nav.map(([id,Icon])=><button key={id} className={`nav-item ${active===id?'active':''}`} onClick={()=>navigate(id)} aria-current={active===id?'page':undefined}><Icon size={19}/><span>{titles[id]}</span>{id==='replacements'&&pending>0&&<b className="nav-badge">{pending}</b>}{id==='tasks'&&state.tasks.filter(t=>t.status!=='done').length>0&&<b className="nav-count">{state.tasks.filter(t=>t.status!=='done').length}</b>}</button>)}</nav><div className="nav-caption tools-caption">ИНСТРУМЕНТЫ</div><button className={`nav-item ${active==='assistant'?'active':''}`} onClick={()=>navigate('assistant')}><Bot size={20}/><span>ИИ-помощник</span><Sparkles size={14} className="purple-text"/></button>{role!=='student'&&<><button className={`nav-item ${active==='history'?'active':''}`} onClick={()=>navigate('history')}><History size={19}/><span>История действий</span></button><button className={`nav-item ${active==='settings'?'active':''}`} onClick={()=>navigate('settings')}><Settings2 size={19}/><span>Настройки</span></button></>}<div className="sidebar-bottom">{PORTAL_MODE&&<a className="nav-item portal-return" href={PORTAL_HOME}><ArrowLeft size={19}/><span>В личный кабинет</span></a>}<div className="assistant-mini"><img src={appUrl('mascot.png')} alt=""/><div><strong>От задачи к результату</strong><p>Школа работает вместе</p></div></div><span className="demo-label"><span/>{PORTAL_MODE?'Доступ через личный кабинет':active==='schedule'&&(role==='admin'||role==='director')?'Локальный черновик · без публикации':'Локальное демо · вымышленные данные'}</span></div></aside>
  <div className="workspace"><header className="topbar"><button className="icon-btn menu-btn" onClick={()=>setMobile(!mobile)} aria-label="Открыть меню"><Menu/></button><div className="global-search"><Search size={18}/><label className="sr-only" htmlFor="global-search">Поиск по школе</label><input id="global-search" placeholder="Поиск по ученикам, документам, задачам…" value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button className="icon-btn" aria-label="Очистить поиск" onClick={()=>setSearch('')}><X size={15}/></button>}{search&&<div className="search-results" role="region" aria-label="Результаты поиска">{results.length?results.map(x=><button key={x.id} onClick={x.go}><Search size={16}/><span><strong>{x.title}</strong><small>{x.subtitle}</small></span><ChevronRight size={15}/></button>):<Empty>Совпадений нет</Empty>}</div>}</div><span className="term-label">2026 / 2027 <ChevronDown size={12}/></span><div className="notifications-wrap"><button className="icon-btn bell-btn" aria-label="Уведомления" aria-expanded={notifications} onClick={()=>setNotifications(!notifications)}><Bell size={21}/>{unread>0&&<span>{unread}</span>}</button>{notifications&&<div className="notifications-popover"><div className="card-head"><h2>Уведомления</h2><button className="text-btn" onClick={()=>void mutate('/api/notifications/read').catch(()=>{})}>Прочитать все</button></div>{state.notifications.length?state.notifications.slice(0,8).map(n=><div key={n.id} className={`notification ${n.read?'read':''}`}><span className="notification-dot"/><div><strong>{n.title}</strong><p>{n.text}</p><small>{timeText(n.time)}</small></div></div>):<Empty>Новых уведомлений нет</Empty>}</div>}</div><div className="profile"><Avatar name={state.profile.name} color="purple"/><div><strong>{state.profile.name}</strong>{PORTAL_MODE?<small className="portal-profile-title">{state.profile.title}</small>:<><label htmlFor="demo-role" className="sr-only">Демонстрационная роль</label><select id="demo-role" value={demoChoice} onChange={e=>void switchRole(e.target.value)} disabled={busy}><option value="director">Демо · Директор</option><option value="admin">Демо · Завуч</option><option value="teacher">Демо · Учитель</option><option value="teacher:t2">Демо · Учитель замены</option><option value="student">Демо · Ученик</option><option value="accountant">Демо · Бухгалтер</option></select></>}</div></div></header>
  <main id="main-content"><div className="page-heading"><div><div className="breadcrumb">Школа <ChevronRight size={12}/> {roleNames[role]}</div><h1>{titles[active]}</h1><p>{descriptions[active]||'Всё необходимое для учебного дня — в одном месте.'}</p></div><div className="date-chip"><CalendarDays size={19}/><div>Понедельник, 12 октября<small>Демонстрационная учебная неделя</small></div></div></div>
  {busy&&<div className="activity-line" role="status" aria-label="Сохранение изменений"/>}
  {academic?<AcademicPages state={state} page={active} mutate={mutate} toast={toast} navigate={navigate}/>:active==='overview'?<Overview state={state} navigate={navigate} openModal={openModal}/>:active==='schedule'?(role==='admin'||role==='director'?<ScheduleWorkspace/>:<Schedule state={state} navigate={navigate} openModal={openModal}/>):active==='replacements'?<Replacements state={state} mutate={mutate} toast={toast}/>:active==='students'||active==='teachers'?<Directory state={state} page={active} openModal={openModal}/>:active==='tasks'?<Tasks state={state} mutate={mutate} toast={toast}/>:active==='documents'?<Documents state={state} mutate={mutate} toast={toast}/>:active==='clubs'?<Clubs state={state} toast={toast} load={load}/>:active==='analytics'?<Analytics state={state} mutate={mutate} toast={toast} navigate={navigate}/>:active==='assistant'?<Assistant state={state} toast={toast} navigate={navigate}/>:active==='history'?<HistoryPage state={state}/>:<Settings state={state} mutate={mutate} toast={toast}/>}
  <footer className="workspace-footer"><span>Школа.Действие <span className="muted">· вместе к лучшей школе</span></span><span><ShieldCheck size={13}/> {PORTAL_MODE?'Доступ проверяется личным кабинетом':active==='schedule'&&(role==='admin'||role==='director')?'Файл хранится локально · без публикации':'Демонстрация на вымышленных данных'}</span></footer></main></div>
  {toastMessage&&<div className="toast" role="status"><CheckCircle2 size={19}/>{toastMessage}<button className="icon-btn" onClick={()=>setToast('')} aria-label="Скрыть сообщение"><X size={15}/></button></div>}{modal&&<Modal title={modalTitle} onClose={closeModal}>{modal}</Modal>}
 </div>
}

function plural(n:number,one:string,few:string,many:string){return n%100>=11&&n%100<=14?many:n%10===1?one:n%10>=2&&n%10<=4?few:many}

function Overview({state,navigate,openModal}:{state:AppState;navigate:(p:string)=>void;openModal:(t:string,c:ReactNode)=>void}){
 const pending=state.replacements.find(r=>r.status==='pending')
 const recent=pending||state.replacements[0]
 const lesson=state.schedule.find(l=>l.id===recent?.lessonId)
 const absent=state.teachers.find(t=>t.id===recent?.absentTeacherId)
 const candidate=recent?.status==='pending'?(recent.candidateDetails||state.teachers).find(t=>recent.candidates.includes(t.id)&&!t.conflict):state.teachers.find(t=>t.id===recent?.teacherId)
 const classProgress=[...new Set(state.students.map(s=>s.className))].map(className=>{const rows=state.students.filter(s=>s.className===className);return {className,value:Math.round(rows.reduce((n,s)=>n+s.progress,0)/rows.length)}})
 const accountant=state.role==='accountant'
 return <div className="page-content selected-overview">
  <section className="welcome-banner reference-hero"><div className="welcome-copy"><h2>Доброе утро, {state.profile.name.split(' ')[0]}!</h2><p>Всё для спокойного учебного дня</p><button className="btn btn-primary" onClick={()=>navigate(accountant?'clubs':'analytics')}>{accountant?'Открыть кружки и квитанции':'Открыть обзор школы'}<ArrowRight size={18}/></button></div></section>
  <div className="stats-grid reference-stats"><Stat icon={Users} tone="blue" label="Ученики" value={state.school.students} detail="5–11 классы"/><Stat icon={UserRound} tone="green" label="Учителя" value={state.school.teachers} detail="Расписание и материалы"/><Stat icon={GraduationCap} tone="purple" label="Классы" value={state.school.classes} detail="Учебный год 2026/27"/><Stat icon={CheckCircle2} tone="orange" label="Задачи" value={state.tasks.filter(t=>t.status!=='done').length} detail="В едином пространстве"/></div>
  <div className="overview-grid reference-working-grid">
   {accountant?<Card title="Документы на проверке" action={<Tag tone="orange">Согласование</Tag>}><div className="task-preview">{state.documents.slice(0,3).map(d=><button key={d.id} onClick={()=>navigate('documents')}><Glossy icon={FileText} tone="orange"/><div><strong>{d.title}</strong><small>{d.status==='approved'?'Согласован':'Требует проверки'}</small></div><ChevronRight size={18}/></button>)}</div><button className="btn btn-primary" onClick={()=>navigate('documents')}>Открыть документы <ArrowRight size={17}/></button></Card>:<Card className="overview-case" title={<><Glossy icon={ArrowLeftRight} tone="pink"/> Замена учителя</>} action={<Tag tone={recent&&recent.status!=='pending'?'green':'pink'}>{recent?recent.status==='pending'?'На согласовании':'Согласовано':'Рабочий процесс'}</Tag>}>
    {recent?<><div className="overview-case-summary"><Avatar name={absent?.name||'Учитель'} color="pink"/><div><h3>{absent?.name}</h3><p>{lesson?.subject} · {lesson?.className} · {lesson?.time}</p></div></div><div className="overview-candidate"><Avatar name={candidate?.name||'Учитель'} color="green"/><div><strong>{candidate?.name||'Проверьте варианты'}</strong><Tag tone={candidate?'green':'orange'}>{recent.status==='pending'?candidate?'Подходит':'Нужна проверка':'Назначена на урок'}</Tag></div><button className="btn btn-primary" onClick={()=>navigate('replacements')}>{recent.status==='pending'?'Проверить замену':'Посмотреть результат'}<ArrowRight size={16}/></button></div></>:<div className="overview-no-case"><div><h3>Учебный день по плану</h3><p>Если педагог отсутствует, подберём свободного преподавателя и проверим пересечения.</p></div><button className="btn btn-primary" onClick={()=>navigate('replacements')}><Plus size={17}/> Сообщить об отсутствии</button></div>}
   </Card>}
   <Card title={<><CalendarDays size={23}/> Сегодня в расписании</>} action={<button className="text-btn" onClick={()=>navigate('schedule')}>Все уроки <ChevronRight size={16}/></button>}><div className="reference-lessons">{state.schedule.filter(l=>l.day===0).sort((a,b)=>a.slot-b.slot).slice(0,3).map(l=><button key={l.id} onClick={()=>openModal(l.subject,<LessonDetail lesson={l} state={state}/>)}><time>{l.time.split('–')[0]}</time><strong>{l.subject}</strong><Tag tone={l.status==='replacement'?'green':'blue'}>{l.className}{l.status==='replacement'?' · Замена':''}</Tag><ChevronRight size={15}/></button>)}</div></Card>
  </div>
  <div className="overview-bottom reference-bottom"><Card title={<><BarChart3 size={23}/> Учебный прогресс</>} action={<button className="text-btn" onClick={()=>navigate(accountant?'tasks':'analytics')}>Обзор <ChevronRight size={16}/></button>}><div className="reference-progress-chart">{classProgress.map(x=><div key={x.className}><strong>{x.value}%</strong><div><i style={{height:x.value+'%'}}/></div><span>{x.className}</span></div>)}</div><small className="muted">По доступным демонстрационным записям</small></Card><Card title={<><CheckCircle2 size={23}/> Задачи школы</>} action={<button className="text-btn" onClick={()=>navigate('tasks')}>Все задачи <ChevronRight size={16}/></button>}><div className="task-preview reference-tasks">{state.tasks.slice(0,2).map(t=><button key={t.id} onClick={()=>navigate(['schedule','Расписание'].includes(t.category)?accountant?'tasks':'replacements':['documents','Документы'].includes(t.category)?'documents':'tasks')}><span className={`status-dot ${t.status==='done'?'green':t.status==='progress'?'orange':'blue'}`}>{t.status==='done'?<Check size={15}/>:<Clock3 size={15}/>}</span><div><strong>{t.title}</strong><small>{t.owner} · {t.due}</small></div><ChevronRight size={17}/></button>)}</div></Card></div>
 </div>
}

function LessonDetail({lesson,state}:{lesson:Lesson;state:AppState}){const material=state.materials.find(m=>m.id===lesson.materialId);return <div className="lesson-detail"><Tag tone={lesson.status==='replacement'?'green':'blue'}>{lesson.status==='replacement'?'Замена согласована':lesson.status==='completed'?'Урок проведён':'По расписанию'}</Tag><div className="detail-grid"><div><small>Класс и кабинет</small><strong>{lesson.className} · Каб. {lesson.room}</strong></div><div><small>Время</small><strong>{lesson.time}</strong></div><div><small>Преподаватель</small><strong>{lesson.teacherName}</strong></div></div>{material&&<><h3><BookOpen size={18}/> {material.title}</h3><div className="document-content">{material.content}</div><button className="btn btn-secondary" onClick={()=>saveFile('Материалы_урока.txt',material.content)}><Download size={16}/> Скачать материалы</button></>}</div>}

function Schedule({state,navigate,openModal}:{state:AppState;navigate:(p:string)=>void;openModal:(t:string,c:ReactNode)=>void}){
 const [className,setClass]=useState('all'),[subject,setSubject]=useState('all'),[view,setView]=useState('week')
 const lessons=state.schedule.filter(l=>(className==='all'||l.className===className)&&(subject==='all'||l.subject===subject));const slots=[...new Set(lessons.map(l=>l.slot))].sort((a,b)=>a-b)
 return <div className="page-content"><div className="toolbar"><div className="filter-group"><select aria-label="Класс расписания" value={className} onChange={e=>setClass(e.target.value)}><option value="all">Все классы</option>{[...new Set(state.schedule.map(l=>l.className))].map(c=><option key={c}>{c}</option>)}</select><select aria-label="Предмет расписания" value={subject} onChange={e=>setSubject(e.target.value)}><option value="all">Все предметы</option>{[...new Set(state.schedule.map(l=>l.subject))].map(c=><option key={c}>{c}</option>)}</select></div><div className="segmented"><button className={view==='week'?'selected':''} onClick={()=>setView('week')}>Неделя</button><button className={view==='list'?'selected':''} onClick={()=>setView('list')}>Список</button></div><button className="btn btn-primary" onClick={()=>navigate('replacements')}><Sparkles size={16}/> Подобрать замену</button></div><div className="schedule-layout"><Card title="Расписание на неделю" action={<span className="muted small-text">12–16 октября 2026</span>}><div className="table-scroll">{view==='week'?<table className="schedule-table"><thead><tr><th>Время</th>{['Пн','Вт','Ср','Чт','Пт'].map((d,i)=><th key={d}>{d}<small>{12+i} октября</small></th>)}</tr></thead><tbody>{slots.map(slot=><tr key={slot}><th><strong>{lessons.find(l=>l.slot===slot)?.time}</strong><small>{slot} урок</small></th>{[0,1,2,3,4].map(day=><td key={day}>{lessons.filter(l=>l.day===day&&l.slot===slot).map(l=><button className={`lesson-cell ${l.status==='normal'?['blue','purple','green','orange'][(l.slot+l.day)%4]:'green'}`} key={l.id} onClick={()=>openModal(l.subject,<LessonDetail lesson={l} state={state}/>)}><strong>{l.subject}</strong><span>{l.className} · Каб. {l.room}</span><small>{l.teacherName}{l.status!=='normal'?' · '+(l.status==='completed'?'Проведён':'Замена'):''}</small></button>)}</td>)}</tr>)}</tbody></table>:<table><thead><tr><th>День</th><th>Время</th><th>Класс</th><th>Предмет</th><th>Учитель</th></tr></thead><tbody>{lessons.map(l=><tr key={l.id}><td>{['Пн','Вт','Ср','Чт','Пт'][l.day]}</td><td>{l.time}</td><td>{l.className}</td><td><button className="text-btn" onClick={()=>openModal(l.subject,<LessonDetail lesson={l} state={state}/>)}>{l.subject}</button></td><td>{l.teacherName}</td></tr>)}</tbody></table>}</div>{!lessons.length&&<Empty>По выбранным фильтрам уроков нет</Empty>}</Card><div className="schedule-aside"><Card title="Замены на согласовании"><div className="replacement-small">{state.replacements.filter(r=>r.status==='pending').map(r=><div key={r.id}><Tag tone="pink"><CircleAlert size={12}/> Учитель отсутствует</Tag><h3>{state.teachers.find(t=>t.id===r.absentTeacherId)?.name}</h3><p className="muted">{r.reason}</p><button className="btn btn-primary" onClick={()=>navigate('replacements')}>Посмотреть варианты <ArrowRight size={15}/></button></div>)}{!state.replacements.some(r=>r.status==='pending')&&<Empty>Все замены согласованы</Empty>}</div></Card><div className="helper-note"><img src={appUrl('mascot.png')} alt=""/><strong>Учитываем всю школу</strong><p>Предмет, занятость педагога и отсутствие пересечений.</p><span><ShieldCheck size={14}/> Назначение после согласования</span></div></div></div></div>
}

function Replacements({state,mutate,toast}:{state:AppState;mutate:(p:string,b?:unknown)=>Promise<void>;toast:(m:string)=>void}){
 const [selected,setSelected]=useState<Record<string,string>>({}),[loading,setLoading]=useState(false),[form,setForm]=useState(false),[lessonId,setLessonId]=useState(state.schedule[0]?.id||''),[reason,setReason]=useState(''),[filter,setFilter]=useState('all')
 const rows=state.replacements.filter(r=>filter==='all'||r.status===filter)
 const action=async(p:string,b?:unknown)=>{setLoading(true);try{await mutate(p,b);toast(p.endsWith('approve')?'Замена утверждена. Расписание и уведомления обновлены.':p.endsWith('complete')?'Проведение урока подтверждено.':'Отсутствие зарегистрировано. Варианты замены подготовлены.');setForm(false);setReason('')}catch{}finally{setLoading(false)}}
 return <div className="page-content"><div className="toolbar"><div className="tabs">{[['all','Все замены'],['pending','На согласовании'],['approved','Утверждены'],['completed','Проведены']].map(([v,t])=><button className={filter===v?'active':''} key={v} onClick={()=>setFilter(v)}>{t}</button>)}</div>{['admin','director','teacher'].includes(state.role)&&<button className="btn btn-primary" onClick={()=>setForm(true)}><Plus size={16}/> Сообщить об отсутствии</button>}</div><div className="replacement-journey"><section className="replacement-intro"><div className="replacement-intro-icon"><img src={appUrl('mascot.png')} alt=""/></div><div><span className="eyebrow">ПОМОЩНИК ЗАВУЧА</span><h2>Один процесс. Согласованное решение.</h2><p>Проверяем расписание, предмет и нагрузку. Вы выбираете подходящего преподавателя.</p></div><div className="human-control"><ShieldCheck size={22}/><span>Назначает<br/><strong>сотрудник школы</strong></span></div></section><div className="flow-strip">{[['Сообщение',Send],['Подбор вариантов',Sparkles],['Согласование',ShieldCheck],['Расписание',CalendarDays],['Результат',CheckCircle2]].map(([title,Icon],i)=><div key={title as string}><span>{i+1}</span><Icon size={17}/><strong>{title as string}</strong>{i<4&&<ChevronRight size={16}/>}</div>)}</div></div>{rows.map(r=>{const lesson=state.schedule.find(l=>l.id===r.lessonId);const absent=state.teachers.find(t=>t.id===r.absentTeacherId);const appointed=state.teachers.find(t=>t.id===r.teacherId);return <div className="replacement-board" key={r.id}><Card className="absence-card" title={<><CircleAlert size={19}/> Учитель не может провести урок</>}><Avatar name={absent?.name||'Учитель'} color="pink"/><h3>{absent?.name}</h3><p>{lesson?.subject} · {lesson?.className} класс</p><div className="absence-details"><span><Clock3 size={16}/>{lesson?.time}</span><span><School size={16}/>Кабинет {lesson?.room}</span><span><FileText size={16}/>{r.reason}</span></div><Tag tone={r.status==='pending'?'pink':'green'}>{r.status==='pending'?'Требуется согласование':r.status==='approved'?'Замена утверждена':'Урок проведён'}</Tag></Card><Card title={r.status==='pending'?'Предложенные замены':'Результат процесса'} action={<Tag tone="purple"><Sparkles size={12}/> Проверка расписания</Tag>}>{r.status==='pending'?<><p className="muted small-text">Выберите свободного преподавателя. Варианты с пересечениями назначить нельзя.</p><div className="candidate-list">{r.candidates.map(id=>{const t=r.candidateDetails?.find(x=>x.id===id)||state.teachers.find(x=>x.id===id);if(!t)return null;const chosen=selected[r.id]===id;return <button key={id} className={`candidate ${t.conflict?'conflict':'eligible'} ${chosen?'chosen':''}`} disabled={!!t.conflict} onClick={()=>setSelected(v=>({...v,[r.id]:id}))} aria-pressed={chosen}><Avatar name={t.name} color={t.color}/><div><strong>{t.name}</strong><span>{t.subject} · {t.weeklyHours} ч / неделю</span><small className={t.conflict?'orange-text':'green-text'}>{t.conflict||'Свободна · нет пересечений'}</small></div><Tag tone={t.conflict?'orange':'green'}>{t.conflict?'Есть конфликт':'Подходит'}</Tag><span className="candidate-choice">{t.conflict?<CircleAlert size={17}/>:chosen?<><Check size={15}/> Выбрано</>:<>Выбрать <ChevronRight size={15}/></>}</span></button>})}</div><div className="approval-footer"><span><ShieldCheck size={17}/> Изменения вступят в силу после согласования</span><button className="btn btn-primary" disabled={!selected[r.id]||loading||!['director','admin'].includes(state.role)} onClick={()=>void action(`/api/replacements/${r.id}/approve`,{teacherId:selected[r.id]})}>{loading?<LoaderCircle className="spin" size={16}/>:<Check size={16}/>} Утвердить замену</button></div></>:<div className="process-result"><div className="success-heading"><span className="success-symbol"><CheckCircle2 size={38}/></span><div><h3>{r.status==='completed'?'Урок проведён и учтён':'Замена утверждена!'}</h3><p>{appointed?.name} {r.status==='completed'?'провела':'проведёт'} урок вместо {absent?.name}</p></div></div><div className="result-cards">{[[CalendarDays,'Расписание обновлено','Изменение доступно в кабинетах учителя и ученика'],[BookOpen,'Материалы доступны','Новый преподаватель получил материалы занятия'],[Bell,'Уведомления сохранены','Участники увидят изменения в своём кабинете']].map(([Icon,title,text])=><div key={title as string}><Glossy icon={Icon as typeof Users} tone={title==='Расписание обновлено'?'blue':title==='Материалы доступны'?'purple':'green'}/><strong>{title as string}</strong><p>{text as string}</p></div>)}</div>{r.status==='approved'&&(state.role!=='teacher'||lesson?.teacherId===state.profile.userId)&&<button className="btn btn-primary" disabled={loading} onClick={()=>void action(`/api/lessons/${r.lessonId}/complete`)}><CheckCheck size={17}/> Подтвердить проведение урока</button>}</div>}</Card></div>})}{!rows.length&&<Card><Empty>Замен в этом статусе нет</Empty></Card>}{form&&<Modal title="Сообщить об отсутствии" onClose={()=>setForm(false)}><form onSubmit={e=>{e.preventDefault();void action('/api/replacements',{lessonId,reason})}}><label>Учитель и урок<select aria-label="Учитель и урок" value={lessonId} onChange={e=>setLessonId(e.target.value)}>{state.schedule.map(l=><option key={l.id} value={l.id}>{l.teacherName} · {l.subject} · {l.className} · {l.time}</option>)}</select></label><label>Причина<textarea aria-label="Причина" maxLength={500} required value={reason} onChange={e=>setReason(e.target.value)} placeholder="Например, болезнь преподавателя"/></label><p className="muted">Система проверит доступность преподавателей и подготовит варианты.</p><button className="btn btn-primary" disabled={loading||!reason.trim()}>{loading?'Подбираем варианты…':'Сообщить и подобрать замену'}</button></form></Modal>}</div>
}

function Directory({state,page,openModal}:{state:AppState;page:string;openModal:(t:string,c:ReactNode)=>void}){const [query,setQuery]=useState(''),[classFilter,setClass]=useState('all');const student=page==='students';const rows=student?state.students.filter(s=>(classFilter==='all'||s.className===classFilter)&&s.name.toLowerCase().includes(query.toLowerCase())):state.teachers.filter(t=>(t.name+' '+t.subject).toLowerCase().includes(query.toLowerCase()));return <div className="page-content"><div className="toolbar"><div className="search-field"><Search size={17}/><input aria-label={student?'Поиск ученика':'Поиск учителя'} placeholder={student?'Имя или фамилия ученика':'Имя или предмет учителя'} value={query} onChange={e=>setQuery(e.target.value)}/></div>{student&&<select aria-label="Фильтр класса" value={classFilter} onChange={e=>setClass(e.target.value)}><option value="all">Все классы</option>{[...new Set(state.students.map(s=>s.className))].map(c=><option key={c}>{c}</option>)}</select>}<button className="btn btn-secondary" onClick={()=>saveFile(`${page}.csv`,'\uFEFF'+(student?'Имя;Класс;Посещаемость;Средний балл\n'+(rows as AppState['students']).map(s=>`${s.name};${s.className};${s.attendance};${s.average}`).join('\n'):'Имя;Предмет;Нагрузка\n'+(rows as Teacher[]).map(t=>`${t.name};${t.subject};${t.weeklyHours}`).join('\n')),'text/csv;charset=utf-8')}><Download size={16}/> Скачать список</button></div><Card title={student?'Ученики демонстрационных классов':'Педагогический состав'} action={<Tag>{rows.length} записей</Tag>}><div className="table-scroll"><table><thead><tr><th>{student?'Ученик':'Преподаватель'}</th><th>{student?'Класс':'Предмет'}</th><th>{student?'Посещаемость':'Нагрузка'}</th><th>{student?'Средний балл':'Доступность'}</th><th/></tr></thead><tbody>{rows.map(row=>{const s=row as AppState['students'][number],t=row as Teacher;return <tr key={row.id}><td><div className="person"><Avatar name={row.name} color={student?'blue':t.color} small/><strong>{row.name}</strong></div></td><td>{student?<Tag tone="purple">{s.className}</Tag>:t.subject}</td><td>{student?<div className="inline-progress"><span>{s.attendance}%</span><div><i style={{width:s.attendance+'%'}}/></div></div>:<span>{t.weeklyHours} ч / неделю</span>}</td><td>{student?<Tag tone={s.average>=4?'green':'orange'}>{s.average.toFixed(1)}</Tag>:<Tag tone={t.conflict?'orange':'green'}>{t.conflict?'Есть пересечение':'Доступен'}</Tag>}</td><td><button className="text-btn" onClick={()=>openModal(row.name,<div className="detail-grid"><div><small>{student?'Класс':'Предмет'}</small><strong>{student?s.className:t.subject}</strong></div><div><small>{student?'Учебный прогресс':'Учебная нагрузка'}</small><strong>{student?s.progress+'%':t.weeklyHours+' ч / неделю'}</strong></div><div><small>{student?'Посещаемость':'Статус в расписании'}</small><strong>{student?s.attendance+'%':t.conflict||'Нет пересечений'}</strong></div></div>)}>Открыть <ChevronRight size={14}/></button></td></tr>})}</tbody></table></div>{!rows.length&&<Empty>Ничего не найдено. Измените поиск или фильтр.</Empty>}<p className="table-note">Показаны вымышленные записи для проверки интерфейса.</p></Card></div>}

function Tasks({state,mutate,toast}:{state:AppState;mutate:(p:string,b?:unknown)=>Promise<void>;toast:(m:string)=>void}){const [filter,setFilter]=useState('all'),[form,setForm]=useState(false),[title,setTitle]=useState(''),[description,setDescription]=useState(''),[loading,setLoading]=useState(false);const save=async()=>{setLoading(true);try{await mutate('/api/tasks',{title,description});setForm(false);setTitle('');setDescription('');toast('Задача создана')}catch{}finally{setLoading(false)}};return <div className="page-content"><div className="toolbar"><div className="tabs">{[['all','Все задачи'],['todo','К выполнению'],['progress','В работе'],['done','Готово']].map(([v,n])=><button key={v} className={filter===v?'active':''} onClick={()=>setFilter(v)}>{n}</button>)}</div>{['director','admin','teacher'].includes(state.role)&&<button className="btn btn-primary" onClick={()=>setForm(true)}><Plus size={17}/> Новая задача</button>}</div><div className="task-columns">{(['todo','progress','done'] as const).filter(v=>filter==='all'||v===filter).map((status,i)=><div className="task-column" key={status}><h2><span className={`status-dot ${['blue','orange','green'][i]}`}/>{['К выполнению','В работе','Готово'][i]}<small>{state.tasks.filter(t=>t.status===status).length}</small></h2>{state.tasks.filter(t=>t.status===status).map(t=><article className="card task-card" key={t.id}><Tag tone={['schedule','Расписание'].includes(t.category)?'purple':['documents','Документы'].includes(t.category)?'orange':'blue'}>{t.category==='schedule'?'Расписание':t.category==='documents'?'Документы':'Учебная работа'}</Tag><h3>{t.title}</h3><p>{t.description}</p><div className="task-meta"><Clock3 size={14}/>{t.due}<span>{t.owner}</span></div><label className="sr-only" htmlFor={'status-'+t.id}>Статус задачи {t.title}</label><select id={'status-'+t.id} value={t.status} onChange={e=>void mutate(`/api/tasks/${t.id}/status`,{status:e.target.value}).then(()=>toast('Статус задачи обновлён')).catch(()=>{})}><option value="todo">К выполнению</option><option value="progress">В работе</option><option value="done">Готово</option></select></article>)}{!state.tasks.some(t=>t.status===status)&&<Empty>Задач нет</Empty>}</div>)}</div>{form&&<Modal title="Новая задача" onClose={()=>setForm(false)}><form onSubmit={e=>{e.preventDefault();void save()}}><label>Название<input required maxLength={150} value={title} onChange={e=>setTitle(e.target.value)} placeholder="Что нужно сделать?"/></label><label>Описание<textarea aria-label="Описание" maxLength={1000} value={description} onChange={e=>setDescription(e.target.value)} placeholder="Контекст и ожидаемый результат"/></label><button className="btn btn-primary" disabled={loading||!title.trim()}>{loading?'Сохраняем…':'Создать задачу'}</button></form></Modal>}</div>}

function Documents({state,mutate,toast}:{state:AppState;mutate:(p:string,b?:unknown)=>Promise<void>;toast:(m:string)=>void}){const [filter,setFilter]=useState('all'),[query,setQuery]=useState(''),[selected,setSelected]=useState(''),[loading,setLoading]=useState(false);const docs=state.documents.filter(d=>(filter==='all'||d.status===filter)&&d.title.toLowerCase().includes(query.toLowerCase()));const doc=state.documents.find(d=>d.id===selected);return <div className="page-content"><div className="toolbar"><div className="tabs">{[['all','Все документы'],['review','На согласовании'],['approved','Согласованы'],['draft','Черновики']].map(([v,n])=><button key={v} className={filter===v?'active':''} onClick={()=>setFilter(v)}>{n}</button>)}</div><div className="search-field"><Search size={16}/><input aria-label="Поиск документа" placeholder="Поиск по названию" value={query} onChange={e=>setQuery(e.target.value)}/></div></div><div className="documents-grid">{docs.map(d=><button className="card document-card" key={d.id} onClick={()=>setSelected(d.id)}><div><Glossy icon={FileText} tone={d.status==='approved'?'green':'purple'}/><Tag tone={d.status==='review'?'orange':d.status==='approved'?'green':'blue'}>{d.status==='review'?'На согласовании':d.status==='approved'?'Согласован':'Черновик'}</Tag></div><h3>{d.title}</h3><p>{d.type}</p><div className="document-meta"><span>{d.author}</span><time>{d.date}</time></div></button>)}</div>{!docs.length&&<Card><Empty>Документов по этому запросу нет</Empty></Card>}{doc&&<Modal title={doc.title} onClose={()=>setSelected('')}><Tag tone={doc.status==='approved'?'green':'orange'}>{doc.status==='approved'?'Согласован':'Требует проверки'}</Tag><div className="document-content">{doc.content}</div><div className="modal-actions"><button className="btn btn-secondary" onClick={()=>saveFile(doc.title+'.txt',doc.content)}><Download size={16}/> Скачать</button>{doc.status==='review'&&['director','admin','accountant'].includes(state.role)&&<button className="btn btn-primary" disabled={loading} onClick={async()=>{setLoading(true);try{await mutate(`/api/documents/${doc.id}/approve`);setSelected('');toast('Документ согласован')}catch{}finally{setLoading(false)}}}><Check size={16}/> Согласовать документ</button>}</div></Modal>}</div>}

type Invoice={id:string;studentId:string;studentName:string;className:string;serviceId:string;service:string;period:string;amountKopeks:number;status:string;date:string}
type FinanceData={students:{id:string;name:string;className:string}[];services:{id:string;title:string;teacher:string;schedule:string;room:string;tariffKopeks:number;color:string}[];invoices:Invoice[];period:string}
function Clubs({state,toast,load}:{state:AppState;toast:(t:string)=>void;load:()=>Promise<unknown>}){
 const [data,setData]=useState<FinanceData|null>(null),[error,setError]=useState(''),[loading,setLoading]=useState(false),[form,setForm]=useState(false),[studentId,setStudentId]=useState(state.students[0]?.id||'s1'),[serviceId,setServiceId]=useState('robotics'),[tab,setTab]=useState('invoices')
 const reload=useCallback(async()=>{try{setData(await api('/api/finance'));setError('')}catch(e){setError(e instanceof Error?e.message:'Нет связи')}},[]);useEffect(()=>{void reload()},[reload,state.role])
 async function action(path:string,body:unknown={}){setLoading(true);try{const result=await api(path,body);await reload();await load();toast(result.duplicate?'Такая квитанция уже существует. Повтор не создан.':path.endsWith('issue')?'Квитанция доступна в кабинете ученика':'Черновик квитанции подготовлен');setForm(false)}catch(e){toast(e instanceof Error?e.message:'Не удалось сохранить')}finally{setLoading(false)}}
 async function download(id:string){try{const r=await apiFetch(`/api/finance/invoices/${encodeURIComponent(id)}/pdf`);if(!r.ok)throw new Error('Не удалось сформировать PDF');const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=id+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('PDF квитанции скачан')}catch(e){toast((e as Error).message)}}
 if(error)return <Card><Empty>{error}</Empty><button className="btn btn-primary" onClick={()=>void reload()}>Повторить загрузку</button></Card>
 if(!data)return <Card><div className="loading-inline"><LoaderCircle className="spin"/>Загружаем кружки и квитанции…</div></Card>
 const pupil=state.role==='student'
 return <div className="page-content"><div className="toolbar"><div className="tabs"><button className={tab==='invoices'?'active':''} onClick={()=>setTab('invoices')}>{pupil?'Мои квитанции':'Квитанции'}</button><button className={tab==='services'?'active':''} onClick={()=>setTab('services')}>Кружки и тарифы</button></div>{!pupil&&<button className="btn btn-primary" onClick={()=>setForm(true)}><Plus size={16}/> Подготовить квитанцию</button>}</div>{!pupil&&<div className="stats-grid"><Stat icon={Users} tone="green" label="Кружки" value={data.services.length} detail="Демонстрационные группы"/><Stat icon={ReceiptText} tone="purple" label="Квитанции" value={data.invoices.length} detail="За октябрь 2026"/><Stat icon={CheckCircle2} tone="blue" label="Выданы ученикам" value={data.invoices.filter(i=>i.status==='issued').length} detail="Доступны в личном кабинете"/><Stat icon={FileText} tone="orange" label="На проверке" value={data.invoices.filter(i=>i.status==='draft').length} detail="До выдачи в кабинет"/></div>}{tab==='services'?<div className="grid-3">{data.services.map(s=><Card key={s.id}><Glossy icon={s.id==='robotics'?Bot:s.id==='chess'?Layers3:BookOpen} tone={s.color}/><h3>{s.title}</h3><p className="muted">{s.teacher}</p><div className="club-info"><span><CalendarDays size={16}/>{s.schedule}</span><span><School size={16}/>Кабинет {s.room}</span></div><strong className="club-tariff">{fmt(s.tariffKopeks)} <small>/ месяц · демотариф</small></strong>{!pupil&&<button className="btn btn-secondary" onClick={()=>{setServiceId(s.id);setForm(true)}}>Подготовить квитанцию <ArrowRight size={15}/></button>}</Card>)}</div>:<div className={pupil?'':'finance-layout'}><Card title={pupil?'Мои квитанции за октябрь':'Квитанции за выбранный период'} action={<Tag>Октябрь 2026</Tag>}><div className="table-scroll"><table><thead><tr><th>Кружок / ученик</th><th>Сумма</th><th>Статус</th><th>Действия</th></tr></thead><tbody>{data.invoices.map(i=><tr key={i.id}><td><strong>{i.service}</strong><small>{pupil?i.id.toUpperCase():`${i.studentName} · ${i.className}`}</small></td><td className="money">{fmt(i.amountKopeks)}</td><td><Tag tone={i.status==='draft'?'orange':'green'}>{i.status==='draft'?'Проверить':'Выдана'}</Tag></td><td><div className="row-actions">{!pupil&&i.status==='draft'&&<button className="btn btn-primary btn-sm" disabled={loading} onClick={()=>void action(`/api/finance/invoices/${i.id}/issue`)}>Выдать ученику</button>}<button className="text-btn" onClick={()=>void download(i.id)}><ArrowDownToLine size={15}/> PDF</button></div></td></tr>)}</tbody></table></div>{!data.invoices.length&&<Empty>Выданных квитанций пока нет</Empty>}<p className="table-note">Образцы документов. Платёжные реквизиты отсутствуют, оплата не проводится.</p></Card>{!pupil&&<Card title="От записи до квитанции" className="invoice-route"><div className="mini-steps">{[['Запись и тариф','Данные кружка и ученика'],['Проверка','Сумма и отсутствие дублей'],['Выдача','Документ в кабинете ученика']].map(([t,d],i)=><div key={t}><span>{i+1}</span><div><strong>{t}</strong><p>{d}</p></div></div>)}</div><div className="info-box"><ShieldCheck size={21}/><p>Каждая квитанция выдаётся сотрудником после проверки.</p></div><button className="btn btn-primary" onClick={()=>setForm(true)}>Подготовить квитанцию <ArrowRight size={16}/></button></Card>}</div>}{form&&<Modal title="Подготовить демонстрационную квитанцию" onClose={()=>setForm(false)}><form onSubmit={e=>{e.preventDefault();void action('/api/finance/invoices',{studentId,serviceId,period:'2026-10'})}}><label>Ученик<select aria-label="Ученик" value={studentId} onChange={e=>setStudentId(e.target.value)}>{data.students.map(s=><option value={s.id} key={s.id}>{s.name} · {s.className}</option>)}</select></label><label>Кружок<select aria-label="Кружок" value={serviceId} onChange={e=>setServiceId(e.target.value)}>{data.services.map(s=><option key={s.id} value={s.id}>{s.title} — {fmt(s.tariffKopeks)}</option>)}</select></label><div className="invoice-summary"><span>Октябрь 2026 · демотариф</span><strong>{fmt(data.services.find(s=>s.id===serviceId)?.tariffKopeks||0)}</strong></div><p className="muted">Создаётся черновик. Выдача ученику — отдельным действием после проверки.</p><button className="btn btn-primary" disabled={loading}>{loading?'Подготавливаем…':'Создать черновик'}</button></form></Modal>}</div>
}

function Analytics({state,mutate,toast,navigate}:{state:AppState;mutate:(p:string,b?:unknown)=>Promise<void>;toast:(t:string)=>void;navigate:(p:string)=>void}){const [period,setPeriod]=useState('month'),[metric,setMetric]=useState('progress');const average=state.students.length?state.students.reduce((a,s)=>a+s.average,0)/state.students.length:0;const attendance=state.students.length?Math.round(state.students.reduce((a,s)=>a+s.attendance,0)/state.students.length):0;const values=period==='month'?[72,78,71,85,89,82]:[68,76,80,87,92,89];const columns=metric==='progress'?values:values.map(v=>Math.min(v+8,100));return <div className="page-content"><div className="toolbar"><Tag tone="blue"><BarChart3 size={14}/> Учебная работа школы</Tag><select aria-label="Период аналитики" value={period} onChange={e=>setPeriod(e.target.value)}><option value="month">Текущий месяц</option><option value="term">Учебная четверть</option></select><button className="btn btn-secondary" onClick={()=>saveFile('Обзор_школы.csv','\uFEFFПоказатель;Значение\nУченики;'+state.school.students+'\nСредний балл;'+average.toFixed(2)+'\nПосещаемость;'+attendance+'\nПодтверждённые замены;'+state.replacements.filter(r=>r.status==='completed').length,'text/csv;charset=utf-8')}><Download size={16}/> Скачать сводку</button></div><div className="stats-grid"><Stat icon={Users} tone="blue" label="Ученики" value={state.school.students} detail="По списку демошколы"/><Stat icon={BarChart3} tone="purple" label="Средний балл" value={average.toFixed(1)} detail="По демонстрационным записям"/><Stat icon={CheckCircle2} tone="green" label="Посещаемость" value={attendance+'%'} detail="По демонстрационным записям"/><Stat icon={ArrowLeftRight} tone="orange" label="Проведённые замены" value={state.replacements.filter(r=>r.status==='completed').length} detail="Подтверждено в системе"/></div><div className="grid-2"><Card title="Выполнение заданий" action={<select aria-label="Показатель графика" value={metric} onChange={e=>setMetric(e.target.value)}><option value="progress">Прогресс</option><option value="attendance">Посещаемость</option></select>}><div className="bar-chart"><div className="chart-labels"><span>100%</span><span>75%</span><span>50%</span><span>25%</span></div><div className="chart-bars">{columns.map((v,i)=><div key={i}><div className="bar-pair"><i style={{height:'92%'}}/><b style={{height:v+'%'}}><span>{v}%</span></b></div><small>{period==='month'?['1 нед.','2 нед.','3 нед.','4 нед.','5 нед.','6 нед.'][i]:['Сент.','Окт.','Нояб.','Дек.','Янв.','Фев.'][i]}</small></div>)}</div></div><div className="chart-legend"><span><i className="blue"/>Пример фактической динамики</span><span><i className="light-blue"/>Учебный ориентир</span></div><small className="muted">Иллюстративный график для демонстрации интерфейса.</small></Card><Card title="Посещаемость"><div className="donut-section"><div className="donut" style={{background:`conic-gradient(#4386ff 0% ${attendance}%,#ad8dff ${attendance}% 100%)`}}><div><strong>{attendance}%</strong><small>посещаемость</small></div></div><div className="donut-legend"><span><i className="blue"/>Присутствовали <strong>{attendance}%</strong></span><span><i className="purple"/>Причина уточняется <strong>{100-attendance}%</strong></span><p className="muted">По доступным учебным записям. Уточнение причины пропуска оформляется как задача.</p></div></div></Card></div><div className="analytics-bottom"><Card title="Нагрузка преподавателей"><div className="load-chart">{state.teachers.map(t=><div key={t.id}><span>{t.name}</span><div><i style={{width:Math.min(t.weeklyHours/36*100,100)+'%'}}/></div><strong>{t.weeklyHours} ч</strong></div>)}</div></Card><Card title="Процессы школы"><div className="operational-stats">{[[ListTodo,'Открытые задачи',state.tasks.filter(t=>t.status!=='done').length,'blue'],[FileText,'На согласовании',state.documents.filter(d=>d.status==='review').length,'orange'],[ArrowLeftRight,'Замены на проверке',state.replacements.filter(r=>r.status==='pending').length,'purple'],[CheckCircle2,'Подтверждённые уроки',state.replacements.filter(r=>r.status==='completed').length,'green']].map(([Icon,t,n,tone])=><button key={t as string} onClick={()=>navigate(t==='На согласовании'?'documents':t==='Открытые задачи'?'tasks':'replacements')}><Glossy icon={Icon as typeof Users} tone={tone as string}/><span>{t as string}</span><strong>{n as number}</strong><ChevronRight size={14}/></button>)}</div></Card><Card title="Предложения помощника"><div className="recommendations">{[['Уточнить причины пропусков','Проверить учебную посещаемость'],['Провести разбор сложной темы','Подготовить материалы по математике'],['Проверить нагрузку учителей','Распределить занятия без пересечений']].map(([t,d])=><div key={t}><span><Sparkles size={15}/></span><div><strong>{t}</strong><p>{d}</p><button className="text-btn" onClick={()=>void mutate('/api/tasks',{title:t,description:d}).then(()=>toast('Поручение создано в задачах')).catch(()=>{})}>Создать поручение <ArrowRight size={13}/></button></div></div>)}</div></Card></div></div>}

function Assistant({state,toast,navigate}:{state:AppState;toast:(t:string)=>void;navigate:(p:string)=>void}){const [messages,setMessages]=useState<{role:string;text:string}[]>([]),[text,setText]=useState(''),[loading,setLoading]=useState(false),[error,setError]=useState('');const bottom=useRef<HTMLDivElement>(null);useEffect(()=>{bottom.current?.scrollIntoView({behavior:'smooth',block:'nearest'})},[messages,loading]);async function send(message:string){if(!message.trim()||loading)return;setText('');setError('');setMessages(m=>[...m,{role:'user',text:message}]);setLoading(true);try{const result=await api('/api/assistant',{message});setMessages(m=>[...m,{role:'assistant',text:result.reply}])}catch(e){setError((e as Error).message);toast('Помощник недоступен. Запрос можно повторить.')}finally{setLoading(false)}}const starters=state.role==='student'?['Как наверстать пропущенную тему?','Объясни сложную тему','Где посмотреть задания?']:['Как подобрать замену учителю?','Какие документы ждут согласования?','Что требует внимания сегодня?'];return <div className="assistant-layout"><Card className="chat-card"><div className="chat-heading"><Glossy icon={Bot} tone="purple"/><div><h2>Школьный помощник</h2><p><span className="live-dot"/> Демонстрационные сценарии</p></div><Tag tone="purple"><Sparkles size={12}/> Демо</Tag></div><div className="chat-messages">{!messages.length&&<div className="chat-intro"><img src={appUrl('mascot.png')} alt=""/><h2>Чем помочь сегодня?</h2><p>Помогу разобраться с задачей и найти<br/>нужный раздел школьного кабинета.</p><div>{starters.map(t=><button key={t} onClick={()=>void send(t)}>{t}<ArrowRight size={14}/></button>)}</div></div>}{messages.map((m,i)=><div key={i} className={`chat-message ${m.role}`}><span>{m.role==='assistant'?<Bot size={19}/>:<UserRound size={19}/>}</span><div>{m.text}</div></div>)}{loading&&<div className="chat-message assistant"><span><Bot size={19}/></span><div className="typing-dots"><i/><i/><i/></div></div>}{error&&<div className="inline-error"><CircleAlert size={18}/>{error}<button className="text-btn" onClick={()=>void send(messages.filter(m=>m.role==='user').at(-1)?.text||'Помоги с задачами')}>Повторить</button></div>}<div ref={bottom}/></div><form className="chat-input" onSubmit={e=>{e.preventDefault();void send(text)}}><label className="sr-only" htmlFor="assistant-message">Сообщение помощнику</label><input id="assistant-message" maxLength={2000} value={text} onChange={e=>setText(e.target.value)} placeholder="Напишите вопрос или опишите задачу…"/><button className="btn btn-primary" disabled={loading||!text.trim()} aria-label="Отправить сообщение"><Send size={18}/></button></form><p className="chat-disclaimer">Подготовленные ответы на учебные примеры. Внешняя ИИ-модель ещё не подключена.</p></Card><div className="assistant-aside"><Card title="Помощь в школьных процессах"><div className="assistant-links">{(state.role==='student'?[['Мои уроки','my-lessons',CalendarDays],['Задания','assignments',ListTodo],['Библиотека','library',BookOpen]]:state.role==='accountant'?[['Кружки и квитанции','clubs',ReceiptText],['Открыть документы','documents',FileText],['Посмотреть задачи','tasks',ListTodo]]:[['Подобрать замену','replacements',ArrowLeftRight],['Открыть документы','documents',FileText],['Посмотреть задачи','tasks',ListTodo]]).map(([t,p,Icon])=><button key={t as string} onClick={()=>navigate(p as string)}><Icon size={18}/>{t as string}<ChevronRight size={15}/></button>)}</div></Card><div className="helper-note"><ShieldCheck size={28}/><strong>Решение остаётся за человеком</strong><p>Изменения расписания и выдача квитанций требуют согласования сотрудника.</p></div></div></div>}

function HistoryPage({state}:{state:AppState}){const [query,setQuery]=useState('');const items=state.history.filter(h=>(h.title+h.detail+h.actor).toLowerCase().includes(query.toLowerCase()));return <div className="page-content"><div className="toolbar"><div className="search-field"><Search size={17}/><input aria-label="Поиск в истории" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Поиск по действиям и участникам"/></div><button className="btn btn-secondary" onClick={()=>saveFile('История_действий.txt',items.map(h=>`${timeText(h.time)} · ${h.actor}\n${h.title}\n${h.detail}`).join('\n\n'))}><Download size={16}/> Скачать журнал</button></div><Card title="Журнал школьных процессов" action={<Tag tone="green"><ShieldCheck size={12}/> Сохранено на сервере</Tag>}><div className="history-list">{items.map(h=><div key={h.id}><span><CheckCircle2 size={20}/></span><div><strong>{h.title}</strong><p>{h.detail}</p><small>{h.actor} · {timeText(h.time)}</small></div></div>)}</div>{!items.length&&<Empty>Действий по запросу нет</Empty>}</Card></div>}
function Settings({state,mutate,toast}:{state:AppState;mutate:(p:string,b?:unknown)=>Promise<void>;toast:(t:string)=>void}){const [reset,setReset]=useState(false),[busy,setBusy]=useState(false);if(PORTAL_MODE)return <div className="grid-2"><Card title="Школьный кабинет"><div className="detail-grid"><div><small>Организация</small><strong>{state.school.name}</strong></div><div><small>Текущая роль</small><strong>{roleNames[state.role]}</strong></div></div><div className="info-box"><ShieldCheck size={22}/><p>Доступ к школьному кабинету проверяется личным кабинетом.</p></div><a className="btn btn-secondary" href={PORTAL_HOME}><ArrowLeft size={16}/> В личный кабинет</a></Card></div>;return <div className="grid-2"><Card title="Демонстрационная школа"><div className="detail-grid"><div><small>Организация</small><strong>{state.school.name}</strong></div><div><small>Учебный год</small><strong>2026 / 2027</strong></div><div><small>Текущая роль</small><strong>{roleNames[state.role]}</strong></div></div><div className="info-box"><CircleHelp size={22}/><p>Роли переключаются в шапке. Это локальные демонстрационные кабинеты на вымышленных данных.</p></div></Card><Card title="Подготовка к показу"><p className="muted">Вернуть учебное расписание, согласования, задания и квитанции к исходному демосценарию.</p><button className="btn btn-secondary" disabled={!['director','admin'].includes(state.role)} onClick={()=>setReset(true)}><RefreshCw size={16}/> Восстановить демоданные</button><div className="info-box"><ShieldCheck size={22}/><p>MAX, школьные системы и платёжные сервисы не подключены. Все действия выполняются локально.</p></div></Card>{reset&&<Modal title="Восстановить демонстрацию?" onClose={()=>setReset(false)}><p>Изменения вымышленных уроков, задач и квитанций будут заменены исходным учебным примером.</p><div className="modal-actions"><button className="btn btn-secondary" onClick={()=>setReset(false)}>Отмена</button><button className="btn btn-primary" disabled={busy} onClick={async()=>{setBusy(true);try{await mutate('/api/demo/reset');setReset(false);toast('Демосценарий восстановлен')}catch{}finally{setBusy(false)}}}>Восстановить демоданные</button></div></Modal>}</div>}
